'use strict';
let data=null, selected=new Set(), category='전체';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeUrl(s){try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'#'}catch{return '#'}}
const when=s=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(s));
const title=i=>i.summary?.status==='ok'?i.summary.title_ko:i.title;
function articleLink(a,extra){return `<a class="article" href="${esc(safeUrl(a.url))}" target="_blank" rel="noopener noreferrer">${esc(a.title)} ↗<small>${esc(a.publisher)} · ${esc(extra)}</small></a>`}
function showDetail(code,id){const country=data.countries.find(c=>c.country===code),i=country.issues.find(i=>i.id===id);$('detail-country').textContent=`${country.flag} ${country.name} / ${i.rank}위 / ${i.confidence}`;$('detail-title').textContent=title(i);
 let html=`<div class="notice">${esc(i.summary?.reason||'원문과 확인된 수치 기반')}<br>대중 관심 ${esc(i.public_interest_score??'미관측')} · 언론 확산 ${esc(i.media_attention_score??'미관측')} · 기사 ${i.article_count}건 · 매체 ${i.publisher_count}곳</div>`;
 if(i.summary?.status==='ok')for(const [key,label] of [['what','핵심 요약'],['recent','최근 변화'],['why','주목받는 이유'],['background','배경']])html+=`<h3>${label}</h3><p>${esc(i.summary[key].text)}</p>`;
 html+='<h3>관심도 근거</h3><p class="muted">검색 급상승을 주 순위 기준으로 사용하고, GDELT·현지 RSS는 사건 설명·교차검증에 사용합니다. 이전 기간 대비 보도량 변화는 동등한 표본이 없어 계산하지 않습니다.</p>';
 for(const t of i.trends)html+=`<div class="article"><b>검색어 · ${esc(t.keyword)}</b><small>원천 검색량 구간 ${esc(t.traffic||'미제공')} · 원천 시각 ${when(t.started_at)} KST</small><small>수집 ${when(t.collected_at)} KST · 정확한 횟수가 아닌 구간/하한</small><a href="${esc(safeUrl(t.url))}" target="_blank" rel="noopener noreferrer">Google Trends ↗</a></div>`;
 html+='<h3>관련 기사</h3>';const seen=new Set();let articles=[];for(const a of i.articles)if(!seen.has(a.publisher_id)){seen.add(a.publisher_id);articles.push(a)}articles=[...articles,...i.articles.filter(a=>!articles.includes(a))].slice(0,5);
 for(const a of articles)html+=articleLink(a,`발행 ${when(a.published_at)} / 수집 ${when(a.collected_at)} KST`);
 if(!articles.length)html+='<p class="muted">발행 시각까지 확인된 기사가 없어 보도량은 결측입니다.</p>';
 for(const t of i.trends)for(const a of (t.related_news||[]).slice(0,5))if(!articles.some(b=>b.url===a.url))html+=articleLink(a,'Trends 연결 기사 · 발행 시각 미제공 / 보도량에서 제외');
 html+='<h3>실제 관측된 뉴스 발행일 분포</h3>';const max=Math.max(1,...i.news_series.map(p=>p.count));for(const p of i.news_series)html+=`<div class="chartrow"><span>${esc(p.date)}</span><i style="width:${p.count/max*65}%"></i><b>${p.count}건</b></div>`;
 if(!i.news_series.length)html+='<p class="muted">관측치 없음. 추세를 생성하지 않습니다.</p>';
 html+='<h3>검색 관심 추세</h3><p class="muted">연속 관측이 부족해 검색 추세선은 제공하지 않습니다. 검색 관심과 뉴스 기사량은 합치지 않습니다.</p><h3>해석 한계</h3><p class="muted">GDELT·RSS 표본과 매체 선택 편향이 있습니다. GDELT의 seendate는 최초 관측 시각이며 발행 시각으로 단정하지 않습니다. 검색어가 여러 사건과 관련될 수 있습니다. 제목 유사도는 후보 묶음이며 동일 사건의 확정 판정이 아닙니다.</p>';
 $('detailbody').innerHTML=html;$('detail').showModal();}
function render(){const countries=data.countries.filter(c=>selected.has(c.country));$('countries').innerHTML=data.countries.map(c=>`<button class="country-toggle ${selected.has(c.country)?'active':''}" data-country="${esc(c.country)}" aria-pressed="${selected.has(c.country)}">${c.flag} ${esc(c.name)}</button>`).join('');
 for(const b of $('countries').querySelectorAll('button'))b.onclick=()=>{selected.has(b.dataset.country)?selected.delete(b.dataset.country):selected.add(b.dataset.country);render()};
 const values=[['관측 국가',String(countries.length).padStart(2,'0')],['수집 기사',countries.reduce((n,c)=>n+c.article_count,0)],['검색 급상승 관측',countries.reduce((n,c)=>n+c.trend_count,0)],['복수 신호 이슈',countries.reduce((n,c)=>n+c.issues.filter(i=>i.confidence==='복수 신호 확인').length,0)]];
 $('metrics').innerHTML=values.map(([l,v])=>`<div class="metric"><small>${l}</small><b>${v}</b></div>`).join('');
 $('radar').innerHTML=countries.length?countries.map(c=>{const issues=c.issues.filter(i=>category==='전체'||i.category===category);return `<article class="card"><div class="cardhead"><div><div class="countrytitle"><span>${c.flag}</span>${esc(c.name)}</div><div class="countrymeta">${c.article_count} 기사 · ${c.trend_count} 검색어 · ${when(c.collected_at)}</div></div><span class="pill warn">GDELT + 현지 RSS</span></div>${issues.length?issues.map(i=>`<button class="issue" data-code="${c.country}" data-issue="${i.id}"><span class="rank">${String(i.rank).padStart(2,'0')}</span><div class="issue-body"><div class="issue-title">${esc(title(i))}</div><div class="issue-meta"><span>${esc(i.category)}</span> · <span class="pill">${esc(i.tags.join(' · '))}</span></div><p class="evidence">${i.article_count?`${i.article_count} 기사 · ${i.publisher_count} 매체`:'발행일 확인 기사 없음'} / ${esc(i.confidence)}${i.trend_only?' · 검색 연관 후보':''}</p><p class="evidence">대중 관심 ${esc(i.public_interest_score??'미관측')} · 언론 확산 ${esc(i.media_attention_score??'미관측')}</p></div></button>`).join(''):'<div class="empty">조건에 맞는 충분한 근거가 없습니다.</div>'}</article>`}).join(''):'<div class="empty">국가를 하나 이상 선택해 주세요.</div>';
 for(const b of $('radar').querySelectorAll('[data-issue]'))b.onclick=()=>showDetail(b.dataset.code,b.dataset.issue);
 $('compare').innerHTML='<p class="muted">TOP 5 내 카테고리 구성 · 대중 관심 신호를 주 순위 기준으로 사용합니다. 국가 간 점수의 크기는 비교하지 않습니다.</p><br><div class="compare">'+countries.map(c=>{const counts={};for(const i of c.issues)if(category==='전체'||category===i.category)counts[i.category]=(counts[i.category]||0)+1;return `<div class="comparebox"><b>${c.flag} ${esc(c.name)}</b>${Object.entries(counts).map(([cat,n])=>`<div class="barline"><label>${esc(cat)}</label><div class="bar"><div style="width:${n/5*100}%"></div></div><span>${n}</span></div>`).join('')||'<p class="muted">조건에 맞는 이슈 없음</p>'}</div>`}).join('')+'</div><br><div class="sources"><b>공통 이슈 후보</b>'+ (data.common.filter(i=>i.countries.filter(c=>selected.has(c)).length>1).map(i=>`<p>${esc(i.title)} · ${esc(i.countries.join(', '))}</p>`).join('')||'<p class="muted">현재 근거와 비교 방식으로 확인한 후보가 없습니다. 서로 다른 언어의 동일 이슈를 놓칠 수 있습니다.</p>')+'</div>';
 $('sources').innerHTML=$('sources').innerHTML.replace('검색 급상승 40% · 보도 표본량 35% · 매체 다양성 15% · 관심 지속성 10%','대중 관심도: 검색 급상승 70% · 검색 후보 폭 30% / 언론 보도 확산도: 보도 표본량 60% · 매체 다양성 25% · 관측일 지속성 15%').replace('국가 내부 log(1+x) 정규화.','검색 급상승을 주 순위 기준으로 사용하고 GDELT·RSS는 사건 설명·교차검증용으로 사용합니다. 국가 내부 log(1+x) 정규화.');}
$('theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('pulse-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};
try{if(localStorage.getItem('pulse-theme')==='dark')document.body.classList.add('dark')}catch{}
$('close').onclick=()=>$('detail').close();$('detail').onclick=e=>{if(e.target===$('detail'))$('detail').close()};
$('category').onchange=e=>{category=e.target.value;render()};
for(const b of document.querySelectorAll('.tab'))b.onclick=()=>{for(const t of document.querySelectorAll('.tab'))t.classList.toggle('active',t===b);for(const id of ['radar','compare','sources'])$(id).classList.toggle('hidden',id!==b.dataset.tab);$('section-title').textContent={'radar':'국가별 주요 이슈','compare':'국가별 관심사의 차이','sources':'추적 가능한 출처와 계산 방식'}[b.dataset.tab]};
fetch('./data.json').then(r=>{if(!r.ok)throw new Error('데이터 응답 오류');return r.json()}).then(d=>{data=d;selected=new Set(d.countries.map(c=>c.country));const cats=[...new Set(d.countries.flatMap(c=>c.issues.map(i=>i.category)))].sort();$('category').innerHTML='<option>전체</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');$('dates').textContent=`조회 ${d.window.reference} · 최근 ${d.window.days}일 / 수집 ${when(d.generated_at)} KST`;$('footer-meta').textContent=`실제 RSS 저장본 · GDELT 경로 구현 · ${when(d.generated_at)} KST`;render()}).catch(e=>{$('dates').textContent='데이터 로드 실패';$('radar').innerHTML='<div class="empty">스냅샷을 불러오지 못했습니다. 페이지를 다시 열어 주세요.</div>'});
